{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "Unrestricted public SSH ingress",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The all-protocol ingress rule allows SSH traffic on port 22 from any IPv4 address, exposing attached resources to remote access attempts."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Unrestricted public RDP ingress",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The all-protocol ingress rule allows RDP traffic on port 3389 from any IPv4 address, exposing attached resources to remote access attempts."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Unrestricted public HTTP ingress",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The all-protocol ingress rule permits HTTP traffic on port 80 from 0.0.0.0/0 rather than restricting exposure to explicitly required traffic."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Unrestricted ingress on all protocols and ports",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group allows all inbound protocols and ports from 0.0.0.0/0, exposing any attached resource to arbitrary internet traffic."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Unrestricted egress on all protocols and ports",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group allows outbound traffic to any IPv4 destination over every protocol and port, enabling unrestricted external communication."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n}\n",
  "fix_summary": "Removed the unrestricted ingress and egress rules. The security group now denies inbound and outbound traffic until narrowly scoped rules are explicitly defined."
}
